// Des: Tests for the command dispatcher end to end on the fake site
// Flo: status JSON > pause blocks run > ask in plain words > ledger + log output > unlock > login ok and login timeout > unknown job
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ct-ctrl-runz-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const runz = @import("ct-ctrl-runz.zig"); const targ = @import("ct-ctrl-args.zig");
fn has(rig: *rigz.Rig, needle: []const u8) bool { return std.mem.find(u8, rig.sink.items, needle) != null; }
fn go(rig: *rigz.Rig, argv: []const []const u8) !u8 { rig.conf.noti_chai_orde = &.{"file"}; rig.conf.lang_main_code = "en"; var cx = rig.ctx(.dry); cx.statd = try std.fmt.allocPrint(cx.aren, ".zig-cache/tmp/{s}", .{rig.tmpz.sub_path}); cx.dataroot = cx.statd; cx.grant = "nobody-zz:(OI)(CI)F"; const args = try targ.argsRead(argv); cx.mode = args.mode(); return runz.dispatch(&cx, args); }
test "status --json is valid JSON with all caps and no browser used" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{ "status", "--json" })); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const val = try std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), std.mem.trim(u8, rig.sink.items, "\n"), .{}); try std.testing.expectEqualStrings("fb", val.object.get("app").?.string); try std.testing.expectEqual(@as(usize, 12), val.object.get("caps").?.array.items.len); }
test "run post --live via dispatch posts; pause stops the next run; resume allows it" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{ "run", "post", "--live", "--text", "via dispatch" })); try std.testing.expectEqualStrings("via dispatch", rig.waitRec("post", 3000).?); _ = try go(&rig, &.{"pause"}); try std.testing.expectError(error.Paused, go(&rig, &.{ "run", "post", "--live", "--text", "while paused" })); _ = try go(&rig, &.{"resume"}); try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{ "run", "post", "--live", "--text", "after resume" })); }
test "ask understands plain words and runs the job" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{ "ask", "post: Hello from ask", "--live" })); try std.testing.expectEqualStrings("Hello from ask", rig.waitRec("post", 3000).?); try std.testing.expect(has(&rig, "understood: post")); try std.testing.expectError(error.BadUsage, go(&rig, &.{ "ask", "tell me a joke" })); }
test "ledger and log commands print what happened" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); _ = try go(&rig, &.{ "run", "list", "--live", "--title", "Red lamp", "--price", "50", "--group", "Home group" }); _ = rig.waitRec("list", 3000).?; rig.sink.clearRetainingCapacity(); _ = try go(&rig, &.{"ledger"}); try std.testing.expect(has(&rig, "\"Red lamp\"")); try std.testing.expect(has(&rig, "group=\"Home group\"")); rig.sink.clearRetainingCapacity(); _ = try go(&rig, &.{"log"}); try std.testing.expect(has(&rig, "ok")); try std.testing.expect(has(&rig, "mark")); }
test "unlock clears an unsure key; usage errors" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.store.keyTake("some|key", 1); _ = try go(&rig, &.{ "unlock", "some|key" }); try std.testing.expectEqual(@import("st-stat-main.zig").Take.go, try rig.store.keyTake("some|key", 2)); try std.testing.expectError(error.BadUsage, go(&rig, &.{"unlock"})); try std.testing.expectError(error.NoJob, go(&rig, &.{ "run", "nope" })); try std.testing.expectError(error.BadUsage, go(&rig, &.{"run"})); try std.testing.expectError(error.BadUsage, go(&rig, &.{"zzz"})); }
test "login succeeds on a normal page and times out on the login page" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.brow_time_seco = 1; try std.testing.expectEqual(@as(u8, 0), try go(&rig, &.{"login"})); try std.testing.expect(has(&rig, "logged in")); var cx = rig.ctx(.dry); cx.base = try std.fmt.allocPrint(cx.aren, "{s}/login/", .{rig.base()}); try std.testing.expectError(error.Timeout, runz.dispatch(&cx, try targ.argsRead(&.{"login"}))); }
test "halt during a live run is logged and shows in status" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectError(error.Halted, @import("ru-post-main.zig").postTo(&cx, "x", "/checkpoint/9/", .post)); rig.sink.clearRetainingCapacity(); _ = try go(&rig, &.{ "status", "--json" }); try std.testing.expect(has(&rig, "\"last_halt\":\"checkpoint\"")); }
test "jobs lists every job with its risk, routines too" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); _ = try go(&rig, &.{"jobs"}); try std.testing.expect(has(&rig, "post-photo")); try std.testing.expect(has(&rig, "friend-unfriend")); try std.testing.expect(has(&rig, "X (needs OK)")); try std.testing.expect(has(&rig, "cap:evnt")); }
test "plan, approve and flow run as commands: risky item waits for one approval, then runs" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.flow_list = &.{.{ .name = "morning", .jobs = &.{ .{ .job = "post-save", .url = "/posts/1" }, .{ .job = "friend-unfriend", .url = "/people/7" } } }}; _ = try go(&rig, &.{ "plan", "morning" }); try std.testing.expect(has(&rig, "2. [NEEDS OK] friend-unfriend")); try std.testing.expect(has(&rig, "fb approve all")); _ = try go(&rig, &.{ "approve", "all" }); try std.testing.expect(has(&rig, "approved: 1 item(s)")); _ = try go(&rig, &.{ "approve", "all" }); try std.testing.expect(has(&rig, "approved: 0 item(s)")); _ = try go(&rig, &.{ "flow", "run", "morning", "--live" }); try std.testing.expect(rig.waitPre("btn|Save post|", 4000)); try std.testing.expect(rig.waitPre("btn|Unfriend|", 4000)); try std.testing.expect(has(&rig, "2 done")); try std.testing.expectEqual(@as(usize, 1), rig.mock.recNum("btn") - rig.mock.recNum("btn") + 1); }
test "setup saves consent only with --yes; live is refused without it" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.base_bizz_main = rig.base(); try rig.store.metaSet("consent", 0); try std.testing.expectError(error.NoConsent, go(&rig, &.{ "run", "post-save", "--live", "--url", "/posts/1" })); rig.conf.brow_time_seco = 2; _ = try go(&rig, &.{"setup"}); try std.testing.expect(has(&rig, "To accept and turn on live runs, run: fb setup --yes")); try std.testing.expectError(error.NoConsent, go(&rig, &.{ "run", "post-save", "--live", "--url", "/posts/1" })); _ = try go(&rig, &.{ "setup", "--yes" }); try std.testing.expect(has(&rig, "consent saved")); _ = try go(&rig, &.{ "run", "post-save", "--live", "--url", "/posts/1" }); try std.testing.expect(rig.waitPre("btn|Save post|", 4000)); }
test "owner tools as commands: doctor, snap, read, report, backup, export, purge, resume" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.brow_vers_minz = 1; _ = try go(&rig, &.{ "doctor", "noti-mark" }); try std.testing.expect(has(&rig, "doctor: 1 ok, 0 missing")); _ = try go(&rig, &.{ "snap", "/notifications", "noti" }); try std.testing.expect(has(&rig, "saved ")); _ = try go(&rig, &.{ "read", "noti" }); try std.testing.expect(has(&rig, "1. Is this still available?")); _ = try go(&rig, &.{"report"}); try std.testing.expect(has(&rig, "report saved")); _ = try go(&rig, &.{"export"}); try std.testing.expect(has(&rig, "exported")); _ = try go(&rig, &.{"purge"}); try std.testing.expect(has(&rig, "purged")); try rig.store.metaSet("unsafe_until", @import("ru-wait-hand.zig").realMs(rig.iozz) + 100000); _ = try go(&rig, &.{"resume"}); try std.testing.expectEqual(@as(i64, 0), try rig.store.metaGet("unsafe_until")); try std.testing.expectError(error.BadUsage, go(&rig, &.{"snap"})); try std.testing.expectError(error.BadUsage, go(&rig, &.{ "flow", "run" })); try std.testing.expectError(error.BadFlow, go(&rig, &.{ "flow", "run", "nope" })); }
